const CACHE = 'viva-cuba-mother-v0.9.1-mami';
const APP_CACHE_PREFIX = 'viva-cuba-';
const SHELL = [
  './',
  './index.html',
  './app.js',
  './install.js',
  './owner-entry.js',
  './owner-user.js',
  './global-identity-entry.js',
  './global-owner-entry.js',
  './lib/desaplicaxi-api.mjs',
  './call.js',
  './version.js',
  './sync.js',
  './release.json',
  './styles.css',
  './install.css',
  './owner-entry.css',
  './manifest.webmanifest',
  './icon.svg',
  './lib/core.mjs',
  './lib/release-core.mjs',
  './owner.html'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(SHELL))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys
          .filter((key) => key.startsWith(APP_CACHE_PREFIX) && key !== CACHE)
          .map((key) => caches.delete(key))
      ))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

async function networkFirst(request, fallbackKey = null, cacheResult = true) {
  const cache = await caches.open(CACHE);
  try {
    const response = await fetch(request, { cache: 'no-store' });
    if (cacheResult && response.ok) await cache.put(fallbackKey || request, response.clone());
    return response;
  } catch (error) {
    const cached = await cache.match(fallbackKey || request);
    if (cached) return cached;
    throw error;
  }
}

async function cacheFirstWithRefresh(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);
  const refresh = fetch(request).then(async (response) => {
    if (response.ok) await cache.put(request, response.clone());
    return response;
  }).catch(() => null);
  return cached || refresh || Response.error();
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, './index.html', true));
    return;
  }

  if (url.pathname.endsWith('/release.json')) {
    event.respondWith(networkFirst(request, null, false));
    return;
  }

  if (['script', 'style', 'worker', 'manifest'].includes(request.destination) || /\.(?:js|mjs|css|json)$/.test(url.pathname)) {
    event.respondWith(networkFirst(request));
    return;
  }

  if (['image', 'font'].includes(request.destination)) {
    event.respondWith(cacheFirstWithRefresh(request));
    return;
  }

  event.respondWith(networkFirst(request));
});

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const INVITE_RE = /VCM-[A-HJ-NP-Z2-9]{4}(?:-[A-HJ-NP-Z2-9]{4}){3}/i;
const ROOM_RE = /^VivaCubaPilot-[A-HJ-NP-Z2-9]{20,40}$/;
const DX_RE = /^DX-[A-HJ-NP-Z2-9]{8}$/;
const OWNER_SECRET_RE = /^OWN-[A-F0-9]{6}(?:-[A-F0-9]{6}){3}$/i;

function secureBytes(length) {
  const out = new Uint8Array(length);
  globalThis.crypto.getRandomValues(out);
  return out;
}

function randomChars(length) {
  const bytes = secureBytes(length);
  let out = '';
  for (let i = 0; i < length; i += 1) {
    out += ALPHABET[bytes[i] % ALPHABET.length];
  }
  return out;
}

export function isValidInvite(code) {
  return typeof code === 'string' && new RegExp(`^${INVITE_RE.source}$`, 'i').test(code.trim());
}

export function isValidRoom(room) {
  return typeof room === 'string' && ROOM_RE.test(room.trim());
}

export function isValidOwnerSecret(secret) {
  return typeof secret === 'string' && OWNER_SECRET_RE.test(secret.trim());
}

export function isOwnerRoute(hash) {
  return String(hash || '').trim().toLowerCase() === '#owner';
}

export function generateInviteCode() {
  return `VCM-${[0, 1, 2, 3].map(() => randomChars(4)).join('-')}`;
}

export function generateRoomId() {
  return `VivaCubaPilot-${randomChars(24)}`;
}

export function generateDx() {
  return `DX-${randomChars(8)}`;
}

export function buildInviteUrl(baseUrl, code, room) {
  if (!isValidInvite(code)) throw new Error('INVALID_INVITE');
  if (!isValidRoom(room)) throw new Error('INVALID_ROOM');
  const url = new URL(baseUrl);
  url.hash = new URLSearchParams({ invite: code.toUpperCase(), room }).toString();
  return url.toString();
}

export function buildInviteMessage(code, link) {
  if (!isValidInvite(code)) throw new Error('INVALID_INVITE');
  const url = new URL(link);
  if (!/^https?:$/.test(url.protocol)) throw new Error('INVALID_LINK');
  return `VIVA CUBA 🇨🇺\nAbre este enlace para entrar:\n${url.toString()}\n\nCódigo de invitación: ${code.toUpperCase()}\n\nCuando aparezca VIVA CUBA, escribe tu nombre y pulsa ACTIVAR Y ENTRAR.`;
}

export function parseInviteHash(hash) {
  const params = new URLSearchParams(String(hash || '').replace(/^#/, ''));
  const invite = (params.get('invite') || '').toUpperCase();
  const room = params.get('room') || '';
  return {
    invite: isValidInvite(invite) ? invite : '',
    room: isValidRoom(room) ? room : '',
  };
}

export function extractInvitePayload(text) {
  const raw = String(text || '');
  const inviteMatch = raw.match(INVITE_RE);
  const invite = inviteMatch ? inviteMatch[0].toUpperCase() : '';

  let room = '';
  const roomParam = raw.match(/[?#&]room=([^\s&#]+)/i);
  if (roomParam) {
    try {
      const decoded = decodeURIComponent(roomParam[1]);
      if (isValidRoom(decoded)) room = decoded;
    } catch {
      room = '';
    }
  }

  if (!room) {
    const directRoom = raw.match(/VivaCubaPilot-[A-HJ-NP-Z2-9]{20,40}/);
    if (directRoom && isValidRoom(directRoom[0])) room = directRoom[0];
  }

  return {
    invite: isValidInvite(invite) ? invite : '',
    room,
  };
}

export function isValidDx(dx) {
  return typeof dx === 'string' && DX_RE.test(dx.trim());
}

export function detectInstallPlatform(userAgent = '', maxTouchPoints = 0) {
  const ua = String(userAgent || '').toLowerCase();
  if (/iphone|ipad|ipod/.test(ua)) return 'ios';
  if (/macintosh/.test(ua) && Number(maxTouchPoints) > 1) return 'ios';
  if (/android/.test(ua)) return 'android';
  if (/cros/.test(ua)) return 'chromeos';
  if (/windows/.test(ua)) return 'windows';
  if (/macintosh|mac os x/.test(ua)) return 'mac';
  if (/linux/.test(ua)) return 'linux';
  return 'other';
}

export function installUiState({ platform = 'other', installed = false, promptAvailable = false } = {}) {
  if (installed) return { label: 'APP INSTALADA', mode: 'installed' };
  if (promptAvailable) return { label: 'DESCARGAR APP', mode: 'prompt' };
  if (platform === 'ios') return { label: 'DESCARGAR APP', mode: 'ios-guide' };
  return { label: 'DESCARGAR APP', mode: 'manual-guide' };
}

export const RELEASE_AUDIT_KEY = 'vc_release_audit_v1';
const SEMVER = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;
const MAX_AUDIT_ROWS = 50;

export function parseSemver(value) {
  const text = String(value || '').trim();
  const match = SEMVER.exec(text);
  if (!match) throw new Error('INVALID_RELEASE_VERSION');
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

export function compareSemver(a, b) {
  const left = parseSemver(a);
  const right = parseSemver(b);
  for (let i = 0; i < 3; i += 1) {
    if (left[i] > right[i]) return 1;
    if (left[i] < right[i]) return -1;
  }
  return 0;
}

export function normalizeRelease(input) {
  if (!input || typeof input !== 'object') throw new Error('INVALID_RELEASE_MANIFEST');
  const version = String(input.version || '').trim();
  parseSemver(version);
  const minimumClientVersion = String(input.minimumClientVersion || version).trim();
  parseSemver(minimumClientVersion);
  const channel = String(input.channel || 'stable').trim().toLowerCase();
  if (!['stable', 'preview'].includes(channel)) throw new Error('INVALID_RELEASE_CHANNEL');
  const schemaVersion = Number(input.schemaVersion || 1);
  if (!Number.isInteger(schemaVersion) || schemaVersion < 1) throw new Error('INVALID_RELEASE_SCHEMA');
  const releasedAt = String(input.releasedAt || '').trim();
  if (releasedAt && Number.isNaN(Date.parse(releasedAt))) throw new Error('INVALID_RELEASE_DATE');
  return {
    app: String(input.app || 'VIVA_CUBA'),
    version,
    minimumClientVersion,
    channel,
    schemaVersion,
    releasedAt,
    commit: String(input.commit || ''),
    notes: String(input.notes || ''),
  };
}

export function shouldUpdate(currentVersion, releaseInput) {
  let release;
  try {
    release = normalizeRelease(releaseInput);
    parseSemver(currentVersion);
  } catch {
    return false;
  }
  if (release.channel !== 'stable') return false;
  return compareSemver(release.version, currentVersion) > 0;
}

export function reloadGuardKey(version) {
  parseSemver(version);
  return `vc_release_reload_once:${version}`;
}

export function readReleaseAudit(storage) {
  if (!storage || typeof storage.getItem !== 'function') return [];
  try {
    const parsed = JSON.parse(storage.getItem(RELEASE_AUDIT_KEY) || '[]');
    return Array.isArray(parsed) ? parsed.slice(-MAX_AUDIT_ROWS) : [];
  } catch {
    return [];
  }
}

function safeAuditRow(input) {
  const row = input && typeof input === 'object' ? input : {};
  return {
    at: String(row.at || new Date().toISOString()),
    event: String(row.event || 'release_event').slice(0, 80),
    currentVersion: String(row.currentVersion || '').slice(0, 24),
    targetVersion: String(row.targetVersion || '').slice(0, 24),
    online: Boolean(row.online),
    timezone: String(row.timezone || '').slice(0, 80),
    language: String(row.language || '').slice(0, 32),
    reason: String(row.reason || '').slice(0, 160),
    result: String(row.result || '').slice(0, 80),
  };
}

export function appendReleaseAudit(storage, input) {
  if (!storage || typeof storage.setItem !== 'function') return [];
  const rows = readReleaseAudit(storage);
  rows.push(safeAuditRow(input));
  const bounded = rows.slice(-MAX_AUDIT_ROWS);
  storage.setItem(RELEASE_AUDIT_KEY, JSON.stringify(bounded));
  return bounded;
}

const API_URL = 'https://c--3a979bdd-c400-4762-992d-6168e30ae209-prod.lovable.cloud';
const PUBLISHABLE_KEY = 'sb_publishable_li2NGEbuo4JQevFpNRlWvg_vm7DK1hi';
const DEFAULT_TIMEOUT_MS = 12000;

function clean(value, max = 400) {
  return String(value ?? '').trim().slice(0, max);
}

async function rpc(name, payload = {}, timeoutMs = DEFAULT_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${API_URL}/rest/v1/rpc/${encodeURIComponent(name)}`, {
      method: 'POST',
      mode: 'cors',
      cache: 'no-store',
      headers: {
        apikey: PUBLISHABLE_KEY,
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    const text = await response.text();
    let body = null;
    try { body = text ? JSON.parse(text) : null; } catch { body = text || null; }
    if (!response.ok) {
      const message = body?.message || body?.error || `RPC ${name} falló (${response.status})`;
      throw new Error(message);
    }
    return body;
  } catch (error) {
    if (error?.name === 'AbortError') throw new Error('DESAPLICAXI_TIMEOUT');
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

function deviceMeta() {
  return {
    p_device_label: clean(navigator.userAgentData?.platform || navigator.platform || 'Navegador', 80),
    p_platform: clean(navigator.userAgentData?.platform || navigator.platform || '', 120),
    p_user_agent: clean(navigator.userAgent || '', 400),
  };
}

export function activateGlobalInvitation(code, displayName) {
  return rpc('dx_activate_invitation', {
    p_code: clean(code, 64).toUpperCase(),
    p_display_name: clean(displayName, 60),
    ...deviceMeta(),
  });
}

export function recoverGlobalIdentity(dx, recoveryKey) {
  return rpc('dx_recover_identity', {
    p_dx: clean(dx, 32).toUpperCase(),
    p_recovery_key: clean(recoveryKey, 80).toUpperCase(),
    ...deviceMeta(),
  });
}

export function claimGlobalOwner(setupCode) {
  return rpc('dx_claim_owner_setup', {
    p_setup_code: clean(setupCode, 80).toUpperCase(),
    ...deviceMeta(),
  });
}

export function issueGlobalInvitation(sessionToken, label = '') {
  return rpc('dx_issue_invitation', {
    p_token: clean(sessionToken, 128),
    p_label: clean(label, 120),
    p_ttl_hours: 168,
  });
}

export function whoAmI(sessionToken) {
  return rpc('dx_whoami', { p_token: clean(sessionToken, 128) }, 8000);
}

export function logoutGlobal(sessionToken) {
  return rpc('dx_logout', { p_token: clean(sessionToken, 128) }, 8000);
}

export function classifyOwnerClaimError(error) {
  const message = String(error?.message || error || '').trim();
  const lower = message.toLowerCase();
  if (message === 'DESAPLICAXI_TIMEOUT') return 'TIMEOUT';
  if (/failed to fetch|networkerror|network request failed|load failed|cors/.test(lower)) return 'NETWORK';
  if (/permission denied|42501|not authorized|unauthorized|forbidden/.test(lower)) return 'PERMISSION';
  if (/pgrst202|could not find the function|schema cache|function .* does not exist/.test(lower)) return 'RPC_MISSING';
  if (/setup.*invalid|invalid.*setup|expired|vencid|already used|ya fue usado|setup_invalid_or_expired/.test(lower)) return 'SETUP_INVALID';
  return 'UNKNOWN';
}

export function ownerClaimErrorMessage(error) {
  const kind = classifyOwnerClaimError(error);
  if (kind === 'TIMEOUT') return 'DESAPLICAXI tardó demasiado en responder. Reintenta en unos segundos.';
  if (kind === 'NETWORK') return 'No se pudo alcanzar DESAPLICAXI desde este navegador. Comprueba la conexión y reintenta.';
  if (kind === 'PERMISSION') return 'DESAPLICAXI respondió, pero el RPC OWNER no tiene permiso de ejecución. El SETUP no es el problema.';
  if (kind === 'RPC_MISSING') return 'El RPC OWNER no está publicado en el backend o su caché de esquema no está actualizada. El SETUP no es el problema.';
  if (kind === 'SETUP_INVALID') return 'El código SETUP es inválido, ya fue usado o venció.';
  const detail = String(error?.message || '').trim().slice(0, 180);
  return detail ? `DESAPLICAXI respondió con un error técnico: ${detail}` : 'DESAPLICAXI devolvió un error técnico no identificado.';
}
